export const CELEBRATION_GUIDE_ID='season-celebration';
export const POLAR_STORM_GUIDE_ID='polar-storm';

function copy(lang){
 if(!Object.hasOwn(SEASON_TRANSITION_COPY,lang))throw new Error(`Unsupported season language: ${lang}`);
 return SEASON_TRANSITION_COPY[lang];
}
export function seasonTransitionText(lang,key){
 const value=copy(lang)[key];
 if(typeof value!=='string'||!value.trim())throw new Error(`Missing season translation: ${key} [${lang}]`);
 return value;
}
export function seasonTransitionGuideTitle(lang,id){
 return seasonTransitionText(lang,id===CELEBRATION_GUIDE_ID?'celebrationTitle':'previewTitle');
}
const paragraph=(value,e)=>`<p>${e(value)}</p>`;
const topic=(title,text,e)=>`<section class="st-topic"><h3>${e(title)}</h3>${paragraph(text,e)}</section>`;

export function celebrationGuideHtml(lang,escape){
 const c=copy(lang),e=escape;
 const tasks=[c.marketTask,c.eventTask,c.duelTask,c.rewardTask,c.staminaRule];
 return `<div class="st-guide">${paragraph(c.celebrationIntro,e)}<section class="st-daily"><h3>${e(c.dailyTitle)}</h3>${paragraph(c.dailyIntro,e)}<ol>${tasks.map(task=>`<li>${e(task)}</li>`).join('')}</ol></section><div class="st-topics">${topic(c.marketTitle,c.marketText,e)+paragraph(c.marketRefresh,e)+paragraph(c.marketBuy,e)}${topic(c.bingoTitle,c.bingoText,e)+paragraph(c.bingoPlanning,e)+`<p class="st-callout"><strong>${e(c.bingoLogin)}</strong></p>`}${topic(c.cashTitle,c.cashText,e)+paragraph(c.cashActivities,e)+paragraph(c.cashLimit,e)}${topic(c.duelTitle,c.duelText,e)+paragraph(c.predictionText,e)}${topic(c.fireworksTitle,c.fireworksText,e)}</div></div>`;
}
function preparationHtml(c,e){
 return `<div class="st-preparation"><article class="st-priority"><h3>${e(c.troopsTitle)}</h3>${paragraph(c.troopsText,e)}${paragraph(c.troopsDetail,e)}</article><article class="st-priority"><h3>${e(c.staminaTitle)}</h3>${paragraph(c.staminaText,e)}${paragraph(c.staminaDetail,e)}</article><article class="st-priority st-priority--tower"><div><h3>${e(c.towerTitle)}</h3>${paragraph(c.towerText,e)}<p class="st-temperature">${e(c.towerLevels)}</p>${paragraph(c.towerDetail,e)}</div><figure><img src="/assets/member/tower-of-victory.webp" width="261" height="300" loading="lazy" decoding="async" alt="${e(c.towerAlt)}"><figcaption>${e(c.towerCaption)}</figcaption></figure></article></div>`;
}
export function season2GuideHtml(lang,escape){
 const c=copy(lang),e=escape;
 return `<div class="st-guide"><h3>${e(c.priorityTitle)}</h3>${paragraph(c.priorityIntro,e)}${preparationHtml(c,e)}<section class="st-topic"><h3>${e(c.morePrepTitle)}</h3><ul class="plain"><li>${e(c.teleportsText)}</li><li>${e(c.ticketsText)}</li><li>${e(c.growthText)}</li><li>${e(c.allianceText)}</li></ul></section><section class="st-preview"><h3>${e(c.previewTitle)}</h3><p class="st-callout">${e(c.previewNotice)}</p><div class="st-topics">${topic(c.temperatureTitle,c.temperatureText,e)}${topic(c.buildingsTitle,c.buildingsText,e)}${topic(c.resourcesTitle,c.resourcesText,e)}${topic(c.objectivesTitle,c.objectivesText,e)}${topic(c.heroesTitle,c.heroesText,e)}</div></section><section class="st-timeline"><h3>${e(c.timelineTitle)}</h3>${paragraph(c.timelineIntro,e)}<ol>${c.weeks.map(week=>`<li>${e(week)}</li>`).join('')}</ol></section></div>`;
}
export function seasonTransitionPage(lang,escape,archiveHtml){
 const c=copy(lang),e=escape;
 const jump=(id,label)=>`<a href="#season" data-season-jump="${id}">${e(label)}</a>`;
 return `<header class="page-heading st-hero"><p class="st-status">${e(c.archiveStatus)}</p><h1>${e(c.heroTitle)}</h1><p>${e(c.heroLead)}</p></header><nav class="st-jumps" aria-label="${e(c.nav)}">${jump('season-now',c.nowTitle)}${jump('season-today',c.todayTitle)}${jump('season-next',c.nextTitle)}${jump('season-archive',c.archiveLink)}</nav><div class="st-overview"><article id="season-now"><h2>${e(c.nowTitle)}</h2>${paragraph(c.nowText,e)}<a href="#guides/${CELEBRATION_GUIDE_ID}">${e(c.celebrationLink)}</a></article><article id="season-today"><h2>${e(c.todayTitle)}</h2>${paragraph(c.todayText,e)}<a href="#guides/${CELEBRATION_GUIDE_ID}">${e(c.guideOpen)}</a></article><article id="season-next"><h2>${e(c.nextTitle)}</h2>${paragraph(c.nextText,e)}<a href="#guides/${POLAR_STORM_GUIDE_ID}">${e(c.preparationLink)}</a></article></div><section class="st-priorities-now"><div class="section-heading"><h2>${e(c.priorityTitle)}</h2><a href="#guides/${POLAR_STORM_GUIDE_ID}">${e(c.preparationLink)}</a></div>${preparationHtml(c,e)}</section><details class="st-details" data-disclosure="season-celebration"><summary>${e(c.celebrationTitle)}</summary><div class="st-details-body">${celebrationGuideHtml(lang,escape)}</div></details><details class="st-details" data-disclosure="season-2-preview"><summary>${e(c.previewTitle)}</summary><div class="st-details-body">${season2GuideHtml(lang,escape)}</div></details><div id="season-archive">${archiveHtml}</div>`;
}
